  intro hφ F hF;
  induction hφ using Hilbert.Deduction.rec! with
  | verum => apply ValidOnFrame.verum;
  | imply₁ => apply ValidOnFrame.imply₁;
  | imply₂ => apply ValidOnFrame.imply₂;
  | and₁ => apply ValidOnFrame.andElim₁;
